import { withHeaders } from "@/framework/api-route";
import { isSameOriginRequest } from "@/framework/csrf";
import { executeServerFn, lookupServerFn, runWithRequest } from "@/framework/server-fn";
import { decode, encode, type WireReply } from "@/framework/wire";
// Every module that defines a server function (generated by scripts/next-routes.ts).
import { serverFnModules } from "./manifest";

/**
 * Server-function dispatcher for the Next.js server build: the endpoint
 * `src/framework/start-client.ts` calls. Same-origin only (TanStack Start's
 * default CSRF rule); errors return their name and message, never a stack.
 * Server-build only: the `.server.ts` extension keeps it out of the static export.
 */
export const dynamic = "force-dynamic";

function reply(body: WireReply, status: number) {
  return new Response(encode(body), {
    status,
    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" },
  });
}

/** Evaluating the modules registers their functions (`createServerFn().handler(fn, id)`). */
const registered = serverFnModules.length;

export async function POST(request: Request, context: { params: Promise<{ id: string }> }) {
  if (!registered) throw new Error("No server-function modules were bundled.");
  if (!isSameOriginRequest(request)) return new Response("Forbidden", { status: 403 });
  const { id } = await context.params;
  let entry: ReturnType<typeof lookupServerFn>;
  try {
    entry = lookupServerFn(decodeURIComponent(id));
  } catch {
    // A malformed escape (`%E0%A4%A`) names no function.
    entry = undefined;
  }
  if (!entry)
    return reply(
      { ok: false, error: { name: "NotFound", message: "Unknown server function." } },
      404,
    );
  let data: unknown;
  try {
    data = decode<{ data?: unknown }>(await request.text()).data;
  } catch {
    return reply({ ok: false, error: { name: "BadRequest", message: "Malformed request." } }, 400);
  }
  try {
    const { value, headers } = await runWithRequest(request, () => executeServerFn(entry, data));
    if (value instanceof Response) return withHeaders(value, headers);
    return withHeaders(reply({ ok: true, result: value }, 200), headers);
  } catch (error) {
    const name = error instanceof Error ? error.name : "Error";
    const message = error instanceof Error ? error.message : "Server function failed.";
    // Errors that carry a client status (`CrossSiteRequestError` is 403) keep it.
    const carried = (error as { status?: unknown } | null)?.status;
    const status =
      name === "UnauthorizedError"
        ? 401
        : typeof carried === "number" && carried >= 400 && carried < 500
          ? carried
          : 500;
    if (status === 500) console.error(`[server-fn] ${id}`, error);
    return reply({ ok: false, error: { name, message } }, status);
  }
}
